// Turns the WhatsApp webhook into one clean item per customer message.
// Status updates (sent, delivered, read) are already dropped by the trigger settings.
const cfg = $('Set Configuration Parameters').first().json;
const maxAgeSeconds = Number(cfg.ignoreMessagesOlderThanMinutes || 15) * 60;
const nowSeconds = Math.floor(Date.now() / 1000);
const skipTypes = ['reaction', 'system', 'ephemeral', 'request_welcome'];
const out = [];

for (const item of $input.all()) {
  const event = item.json || {};
  const messages = Array.isArray(event.messages) ? event.messages : [];
  const contacts = Array.isArray(event.contacts) ? event.contacts : [];
  const phoneNumberId = (event.metadata && event.metadata.phone_number_id) || '';

  for (const m of messages) {
    if (!m || !m.id || !m.from) continue;
    if (skipTypes.includes(m.type)) continue;
    // After downtime Meta re-sends old messages. Do not answer messages that are too old.
    const sentAt = Number(m.timestamp || nowSeconds);
    if (nowSeconds - sentAt > maxAgeSeconds) continue;

    const contact = contacts.find(c => c.wa_id === m.from) || contacts[0] || {};
    let kind = m.type;
    let content = '';
    let mediaId = '';
    let fileName = '';

    if (m.type === 'text') {
      content = (m.text && m.text.body) || '';
    } else if (m.type === 'audio') {
      mediaId = (m.audio && m.audio.id) || '';
    } else if (m.type === 'image') {
      mediaId = (m.image && m.image.id) || '';
      content = (m.image && m.image.caption) || '';
    } else if (m.type === 'document') {
      mediaId = (m.document && m.document.id) || '';
      content = (m.document && m.document.caption) || '';
      fileName = (m.document && m.document.filename) || 'document';
    } else if (m.type === 'button') {
      kind = 'text';
      content = (m.button && (m.button.text || m.button.payload)) || '';
    } else if (m.type === 'interactive') {
      kind = 'text';
      const i = m.interactive || {};
      content = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || '';
    } else if (m.type === 'location') {
      kind = 'text';
      const l = m.location || {};
      const place = [l.name, l.address].filter(Boolean).join(', ');
      content = '[Shared a location' + (place ? ': ' + place : '') + ' (' + l.latitude + ', ' + l.longitude + ')]';
    } else if (m.type === 'contacts') {
      kind = 'text';
      const names = (m.contacts || []).map(c => c.name && c.name.formatted_name).filter(Boolean);
      content = '[Shared a contact card' + (names.length ? ': ' + names.join(', ') : '') + ']';
    } else {
      kind = 'other';
      content = '[The customer sent a ' + m.type + ' message, which this assistant cannot open]';
    }

    if (kind === 'text' && !String(content).trim()) continue;
    if (['audio', 'image', 'document'].includes(kind) && !mediaId) continue;

    out.push({
      json: {
        message_id: m.id,
        phone: m.from,
        contact_name: (contact.profile && contact.profile.name) || '',
        role: 'user',
        kind,
        content: String(content).slice(0, 4000),
        media_id: mediaId,
        file_name: fileName,
        phone_number_id: phoneNumberId,
        status: 'received',
      },
    });
  }
}

return out;

// Turns the result of transcription, image analysis or PDF extraction into plain text
// that the agent can read. If a step failed, it says so instead of stopping the workflow.
const row = $('Log New Messages').item.json;
const cfg = $('Set Configuration Parameters').first().json;
const maxChars = Number(cfg.maxDocumentCharacters || 15000);
const result = $json || {};
const failed = Boolean(result.error);
const caption = String(row.content || '').trim();

let extracted = '';
if (!failed) {
  if (row.kind === 'image') extracted = typeof result.content === 'string' ? result.content : '';
  else extracted = typeof result.text === 'string' ? result.text : '';
}
extracted = extracted.replace(/\s+\n/g, '\n').trim();

let content;
if (row.kind === 'audio') {
  content = extracted
    ? '[Voice note] ' + extracted
    : '[The customer sent a voice note that could not be transcribed]';
} else if (row.kind === 'image') {
  content = extracted
    ? '[Image' + (caption ? ' with caption: "' + caption + '"' : '') + '] What the image shows: ' + extracted
    : '[The customer sent an image that could not be analysed' + (caption ? '. Caption: "' + caption + '"' : '') + ']';
} else {
  const name = row.file_name || 'document';
  if (extracted) {
    const shortened = extracted.length > maxChars;
    content = '[PDF "' + name + '"' + (caption ? ' with caption: "' + caption + '"' : '') + '] Document text:\n' +
      extracted.slice(0, maxChars) + (shortened ? '\n(document shortened)' : '');
  } else {
    content = '[The customer sent a PDF "' + name + '" with no readable text, for example a scanned document]';
  }
}

return { json: { message_id: row.message_id, content } };

// Message buffer: customers often send several short messages in a row.
// Every run waits a few seconds, then only the run that saved the NEWEST message
// for that customer answers. It replies to all of their unanswered messages at once.
const mine = new Set($('Store Message Text').all().map(i => i.json.message_id));
const rows = new Map();
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.message_id) rows.set(r.message_id, r);
}

const byPhone = {};
for (const r of rows.values()) {
  if (!byPhone[r.phone]) byPhone[r.phone] = [];
  byPhone[r.phone].push(r);
}

const out = [];
for (const phone of Object.keys(byPhone)) {
  const list = byPhone[phone].sort((a, b) => Number(a.id) - Number(b.id));
  const newest = list[list.length - 1];
  // A newer message arrived after ours: the run that saved it will answer everything.
  if (!mine.has(newest.message_id)) continue;
  const ready = list.filter(r => r.status === 'pending' && String(r.content || '').trim());
  if (!ready.length) continue;
  out.push({
    json: {
      phone,
      phone_number_id: newest.phone_number_id,
      contact_name: newest.contact_name || '',
      last_message_id: newest.message_id,
      last_row_id: Number(newest.id),
      message_count: ready.length,
      customer_message: ready.map(r => r.content).join('\n'),
    },
  });
}

return out;

// Builds the agent prompt from the saved conversation history (persistent memory).
const cfg = $('Set Configuration Parameters').first().json;
const maxMessages = Number(cfg.memoryMessages || 20);
const owners = $('Select Responder').all().map(i => i.json);
const history = $input.all()
  .map(i => i.json || {})
  .filter(r => r.message_id && String(r.content || '').trim());

return owners.map(o => {
  const past = history
    .filter(r => r.phone === o.phone)
    .sort((a, b) => Number(a.id) - Number(b.id))
    .slice(-maxMessages);
  const lines = past.map(r => (r.role === 'assistant' ? 'You' : 'Customer') + ': ' + String(r.content).slice(0, 1500));
  const prompt = [
    past.length ? 'Conversation so far (oldest first):\n' + lines.join('\n') : 'This is the first message from this customer.',
    '',
    'Customer name on WhatsApp: ' + (o.contact_name || 'unknown'),
    '',
    o.message_count > 1 ? 'New messages from the customer (answer them together):' : 'New message from the customer:',
    o.customer_message,
  ].join('\n');
  return { json: { ...o, prompt, history_messages: past.length } };
});

// Converts the agent answer to WhatsApp formatting and splits long answers
// (WhatsApp text messages are limited to 4096 characters).
const cfg = $('Set Configuration Parameters').first().json;
const LIMIT = 3800;

function toWhatsApp(text) {
  return String(text || '')
    .replace(/```[a-z]*\n?/gi, '')
    .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')
    .replace(/\*\*(.+?)\*\*/g, '*$1*')
    .replace(/__(.+?)__/g, '_$1_')
    .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1: $2')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function split(text) {
  const parts = [];
  let rest = text;
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n\n', LIMIT);
    if (cut < LIMIT / 2) cut = rest.lastIndexOf('. ', LIMIT) + 1;
    if (cut < LIMIT / 2) cut = LIMIT;
    parts.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

const out = [];
$input.all().forEach((item, i) => {
  const o = $('Construct AI Prompt').itemMatching(i).json;
  const reply = toWhatsApp(item.json.output) || cfg.fallbackReply;
  split(reply).forEach((part, n) => {
    out.push({
      json: {
        phone: o.phone,
        phone_number_id: o.phone_number_id,
        reply: part,
        part: n + 1,
      },
      pairedItem: { item: i },
    });
  });
});
return out;

